async function mapLimit(items, limit, fn) {
  const results = new Array(items.length);
  let next = 0; // индекс следующей задачи, общий для всех «воркеров»

  async function worker() {
    while (next < items.length) {
      const i = next++;                    // взяли задачу синхронно
      results[i] = await fn(items[i], i);  // ждём, потом берём следующую
    }
  }

  const workers = Array.from({ length: Math.min(limit, items.length) }, worker);
  await Promise.all(workers);
  return results; // порядок как во входном массиве
}

const { setTimeout: sleep } = require('node:timers/promises');
let active = 0;

mapLimit([300, 100, 200, 100, 100], 2, async (ms, i) => {
  active++;
  console.log(`старт ${i}, в работе: ${active}`);
  await sleep(ms);
  active--;
  return ms * 2;
}).then((r) => console.log(r));

