// суммируем 50 млн чисел порциями по 1 млн
function sumInChunks(n, chunk, done) {
  let i = 0, sum = 0;
  function step() {
    const end = Math.min(i + chunk, n);
    for (; i < end; i++) sum += i;
    if (i < n) setImmediate(step);   // отдать цикл, потом продолжить
    else done(sum);
  }
  step();
}

const start = Date.now();
const timer = setInterval(() => console.log('сервер жив', Date.now() - start), 20);
