async function copy(src, dst) {
  const out = fs.createWriteStream(dst);
  for await (const chunk of fs.createReadStream(src)) {
    if (!out.write(chunk)) await once(out, 'drain'); // приёмник просит паузу
  }
  out.end();                 // данных больше не будет
  await once(out, 'finish'); // всё сброшено в файл
}

