const { Transform } = require('node:stream');
const { StringDecoder } = require('node:string_decoder');

class CsvParser extends Transform {
  constructor() {
    super({ readableObjectMode: true });      // вход: байты, выход: объекты
    this.decoder = new StringDecoder('utf8'); // не рвёт многобайтные символы
    this.tail = '';
    this.columns = null;
  }
  _transform(chunk, encoding, callback) {
    const lines = (this.tail + this.decoder.write(chunk)).split('\n');
    this.tail = lines.pop(); // последняя строка могла оборваться на границе чанка
    for (const line of lines) this.parseLine(line);
    callback();
  }
  _flush(callback) {         // вход закончился: разбираем остаток
    this.parseLine(this.tail + this.decoder.end());
    callback();
  }
  parseLine(line) {
    if (!line.trim()) return;
    const cells = line.trim().split(',');
    if (!this.columns) { this.columns = cells; return; } // первая строка: заголовок
    this.push(Object.fromEntries(this.columns.map((c, i) => [c, cells[i]])));
  }
}
module.exports = { CsvParser };

