class Mini {
  #events = {};                                    // имя события → массив функций
  on(name, fn) { (this.#events[name] ??= []).push(fn); return this; }
  off(name, fn) { this.#events[name] = this.#events[name]?.filter((f) => f !== fn); return this; }
  once(name, fn) { const w = (...a) => { this.off(name, w); fn(...a); }; return this.on(name, w); }
  emit(name, ...args) {
    const list = this.#events[name] ?? [];
    for (const fn of [...list]) fn(...args);       // обходим копию: подписки во время emit не мешают
    return list.length > 0;
  }
}
const m = new Mini();
m.on('hi', (n) => console.log('on', n)).once('hi', (n) => console.log('once', n));
