function httpError(status, message) {
  return Object.assign(new Error(message), { status });
}

async function readJson(req, limit = 1024 * 1024) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {       // req — Readable: читаем по чанкам
    size += chunk.length;
    if (size > limit) throw httpError(413, 'Payload Too Large');
    chunks.push(chunk);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString('utf8'));
  } catch {
    throw httpError(400, 'Invalid JSON'); // кривой JSON — ошибка клиента
  }
}

module.exports = { readJson, httpError };

