function createApp() {
  const stack = [];                            // middleware в порядке регистрации

  function app(req, res) {                     // это и есть обработчик для http.createServer
    let i = 0;
    function next(err) {
      const fn = stack[i++];
      if (!fn) {                               // цепочка кончилась, никто не ответил
        res.statusCode = err ? 500 : 404;
        return res.end(err ? 'Internal Server Error' : 'Not Found');
      }
      const isErrorHandler = fn.length === 4;  // (err, req, res, next)
      try {
        if (err && isErrorHandler) return fn(err, req, res, next);
        if (!err && !isErrorHandler) return fn(req, res, next);
        next(err);                             // не тот тип: пропускаем
      } catch (e) {
        next(e);                               // синхронный throw → к обработчику ошибок
      }
    }
    next();
  }

  app.use = (fn) => { stack.push(fn); return app; };
  return app;
}
module.exports = { createApp };

