const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const { pipeline } = require('node:stream/promises');

const ROOT = path.resolve('public');
const TYPES = { '.html': 'text/html; charset=utf-8', '.css': 'text/css', '.js': 'text/javascript', '.png': 'image/png' };

http.createServer(async (req, res) => {
  try {
    const pathname = decodeURIComponent(new URL(req.url, 'http://x').pathname); // %20 → пробел
    const file = path.join(ROOT, path.normalize(pathname));
    if (!file.startsWith(ROOT + path.sep)) { res.writeHead(403).end(); return; } // защита от ../
    const stat = await fs.promises.stat(file);
    if (!stat.isFile()) throw Object.assign(new Error('not a file'), { code: 'ENOENT' });
    res.writeHead(200, {
      'Content-Type': TYPES[path.extname(file)] ?? 'application/octet-stream',
      'Content-Length': stat.size,                 // размер известен заранее
    });
    await pipeline(fs.createReadStream(file), res); // обратное давление и закрытие файла
  } catch (err) {
    if (res.headersSent) return res.destroy();      // заголовки ушли: остаётся оборвать
    const status = err instanceof URIError ? 400 : err.code === 'ENOENT' ? 404 : 500;
    res.writeHead(status).end();
  }
}).listen(3000);

