class AppError extends Error {
  constructor(message, { status = 500, code = 'INTERNAL', ...options } = {}) {
    super(message, options);      // options может содержать cause
    this.name = new.target.name;  // иначе name останется 'Error'
    this.status = status;
    this.code = code;
  }
}

class NotFoundError extends AppError {
  constructor(what, options) {
    super(`${what} не найден`, { status: 404, code: 'NOT_FOUND', ...options });
  }
}

// cause сохраняет исходную ошибку: в логе будет видна вся цепочка
function parseConfig(raw) {
  try {
    return JSON.parse(raw);
  } catch (err) {
    throw new AppError('Битый файл конфигурации', { cause: err });
  }
}

function handleError(err, res) {
  const known = err instanceof AppError && err.status < 500;
  if (!known) console.error(err); // полный стек и cause — только в лог
  res.writeHead(known ? err.status : 500, { 'content-type': 'application/json' });
  res.end(JSON.stringify(known
    ? { error: err.code, message: err.message }
    : { error: 'INTERNAL' }));     // клиенту никаких подробностей
}

http.createServer(async (req, res) => {
  try {
    const data = await route(req); // route может бросить NotFoundError
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify(data));
  } catch (err) {
    handleError(err, res);
  }
}).listen(3000);

