class LRU {
  constructor(max) { this.max = max; this.map = new Map(); }
  get(key) {
    if (!this.map.has(key)) return undefined;
    const value = this.map.get(key);
    this.map.delete(key);          // переставляем в конец: «недавно использован»
    this.map.set(key, value);
    return value;
  }
  set(key, value) {
    this.map.delete(key);
    this.map.set(key, value);
    if (this.map.size > this.max) {
      this.map.delete(this.map.keys().next().value); // первый ключ — самый давний
    }
  }
}

function track(client) {
  const timer = setInterval(async () => {
    client.status = await fetchStatus(client.id);  // держит client вечно
  }, 5000);
  client.socket.on('close', () => clearInterval(timer)); // без этого — утечка
}

const pending = new Map();
function call(id, payload) {
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject }); // ответ может не прийти никогда
    socket.send(JSON.stringify({ id, payload }));
  });
}

function call(id, payload, ms = 5000) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      pending.delete(id);                              // запись больше не держит промис
      reject(new Error(`нет ответа на запрос ${id}`));
    }, ms);
    const settle = (fn) => (value) => {                // ответ пришёл: убрать таймер и запись
      clearTimeout(timer);
      pending.delete(id);
      fn(value);
    };
    pending.set(id, { resolve: settle(resolve), reject: settle(reject) });
    socket.send(JSON.stringify({ id, payload }));
  });
}

